# PROC statistics registry (inst/registry/proc_stats.csv): one row per
# procedure x statistic (x condition) with its verification status against
# SAS 9.4, generated by tools/update_proc_registry.R from the SAS gold probes
# (never edited by hand).  Statuses:
#   verified     every compared value is bit-identical to SAS
#   partial      verified inside the domain written in `domain`; other inputs
#                fail loud at run time in every mode
#   approximate  some values differ from SAS in the last bits
#   unverified   no SAS evidence yet
# approximate / unverified statistics are gated by `sasonr.strict` exactly like
# functions (see ?sasonr_strict): TRUE (default) fails loud with a condition
# of class `sasonr_not_verified` naming the procedure, the statistic and the
# opt-out; FALSE runs with a `sasonr_unverified` warning.

#' PROC statistics registry
#'
#' One row per procedure and statistic (and condition, such as a WEIGHT
#' statement) with the verification status against SAS 9.4 and the evidence
#' cases.
#' @return A data frame.
#' @keywords internal
#' @export
sas_proc_stat_registry <- function() {
  if (is.null(registry_cache$proc_stats)) {
    f <- system.file("registry", "proc_stats.csv", package = "sasonr")
    registry_cache$proc_stats <- if (nzchar(f)) {
      utils::read.csv(f, stringsAsFactors = FALSE, colClasses = "character")
    } else {
      data.frame(proc = character(), statistic = character(), condition = character(), status = character(),
                 stringsAsFactors = FALSE)
    }
  }
  registry_version_rows(registry_cache$proc_stats, sas_target_version())
}

# PROC SUMMARY shares the MEANS rows; a row with statistic "*" covers every
# statistic under its condition (e.g. any statistic with a WEIGHT statement).
proc_stat_status <- function(proc, stat, condition = "default") {
  reg <- sas_proc_stat_registry()
  proc <- toupper(proc)
  if (proc == "SUMMARY") proc <- "MEANS"
  sel <- reg$proc == proc & reg$condition == condition
  hit <- reg$status[sel & reg$statistic == toupper(stat)]
  if (!length(hit)) hit <- reg$status[sel & reg$statistic == "*"]
  if (length(hit)) hit[1] else NA_character_
}

# Gate one statistic of a procedure (`condition`: "default" or a registry
# condition such as "weight").  Returns invisibly when it may run.
proc_stat_check <- function(proc, stat, line = NULL, condition = "default") {
  st <- proc_stat_status(proc, stat, condition)
  if (!feature_gated(st)) return(invisible())
  cond_txt <- if (identical(condition, "default")) "" else paste0(" (", condition, ")")
  what <- sprintf("PROC %s statistic %s%s %s", toupper(proc), toupper(stat), cond_txt, feature_status_text(st))
  if (!isFALSE(getOption("sasonr.strict", TRUE))) {
    msg <- paste0("Unsupported: ", what, "; set options(sasonr.strict = FALSE) to run it anyway")
    if (!is.null(line) && length(line) == 1 && !is.na(line)) msg <- paste0(msg, " (SAS line ", line, ")")
    rlang::abort(msg, class = c("sasonr_not_verified", "sasonr_unsupported", "sasonr_error"), sas_line = line,
                 kind = "proc_statistic", proc = toupper(proc), name = toupper(stat), status = st)
  }
  warning(structure(class = c("sasonr_unverified", "warning", "condition"),
                    list(message = paste0("sasonr: ", what, if (!is.null(line)) sprintf(" at line %s", line) else ""),
                         call = NULL, kind = "proc_statistic", proc = toupper(proc), name = toupper(stat), status = st)))
  invisible()
}
